const input = $input.all()[0]?.json || {};
const category = input.category || input.niche || 'streetwear';
return [{ json: { category } }];

const category = $('Unpack Input').first().json.category;
const raw = $input.first().json?.choices?.[0]?.message?.content || '[]';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\[[\s\S]*\]/);
let keywords = [];
try { keywords = JSON.parse(match?.[0] || '[]'); } catch(_) {}
return [{ json: { category, keywords } }];
